<template><div class="batch-page"><el-card shadow="never" class="!border-none"><el-form :model="filters" inline><el-form-item label="筛选搜索"><el-input v-model="filters.keyword" clearable placeholder="批次名称" /></el-form-item><el-form-item label="批次状态"><el-select v-model="filters.status" clearable placeholder="全部状态"><el-option v-for="s in statuses" :key="s" :label="s" :value="s" /></el-select></el-form-item><el-form-item><el-button type="primary" @click="resetPage">查询</el-button><el-button @click="reset">重置</el-button><el-button :icon="Download" @click="exportData">数据导出</el-button></el-form-item></el-form></el-card><el-card shadow="never" class="!border-none mt-4"><template #header><div class="heading"><span class="card-title">总批次</span><el-button type="primary" :icon="Plus" @click="openForm()">新增批次</el-button></div></template><el-table :data="paged" stripe table-layout="fixed" class="batch-table"><el-table-column label="批次名称" prop="name" min-width="150" class-name="first-column" label-class-name="first-column" /><el-table-column label="奖码总数" prop="total" min-width="110" /><el-table-column label="待激活数" prop="pending" min-width="110" /><el-table-column label="未扫码量" prop="unscanned" min-width="110" /><el-table-column label="已扫码数" prop="scanned" min-width="110" /><el-table-column label="中奖数量" prop="winning" min-width="110" /><el-table-column label="创建时间" prop="createdAt" min-width="170" /><el-table-column label="批次状态" min-width="120"><template #default="{row}"><el-tag :type="statusType(row.status)">{{ row.status }}</el-tag></template></el-table-column><el-table-column label="操作" min-width="170" class-name="last-column" label-class-name="last-column"><template #default="{row}"><el-button link type="primary" @click="openForm(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table><div class="flex justify-end mt-4"><el-pagination v-model:current-page="page" background layout="total, prev, pager, next" :total="filtered.length" /></div></el-card><el-dialog v-model="visible" :title="editing ? '编辑批次' : '新增批次'" width="480px"><el-form :model="form" label-width="90px"><el-form-item label="批次名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="有效期"><el-date-picker v-model="form.validity" type="daterange" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="批次状态"><el-select v-model="form.status"><el-option v-for="s in statuses" :key="s" :label="s" :value="s" /></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">确定</el-button></template></el-dialog></div></template>
<script lang="ts" setup name="batchTotal">
import { Download, Plus } from '@element-plus/icons-vue'
import { ElMessageBox } from 'element-plus'
type Status = '启用' | '禁用' | '已过期'; interface Batch { id: string; name: string; total: number; pending: number; unscanned: number; scanned: number; winning: number; createdAt: string; status: Status; validity: string[] }
const statuses: Status[] = ['启用', '禁用', '已过期']; const batches = reactive<Batch[]>(Array.from({ length: 18 }, (_, i) => ({ id: `BT${1001 + i}`, name: `2026年${String((i % 6) + 1).padStart(2, '0')}月生产批次${i + 1}`, total: 10000 + i * 800, pending: 1200 + i * 30, unscanned: 6200 - i * 50, scanned: 2600 + i * 80, winning: 120 + i * 5, createdAt: `2026-08-${String(28 - i % 20).padStart(2, '0')} 10:20:00`, status: i % 7 === 0 ? '已过期' : i % 5 === 0 ? '禁用' : '启用', validity: ['2026-08-01', '2026-12-31'] }))); const filters = reactive({ keyword: '', status: '' }); const page = ref(1); const pageSize = 10; const visible = ref(false); const editing = ref(''); const form = reactive({ name: '', validity: [] as string[], status: '启用' as Status }); const filtered = computed(() => batches.filter(b => (!filters.keyword || b.name.includes(filters.keyword.trim())) && (!filters.status || b.status === filters.status))); const paged = computed(() => filtered.value.slice((page.value - 1) * pageSize, page.value * pageSize)); const resetPage = () => { page.value = 1 }; const reset = () => { filters.keyword = ''; filters.status = ''; resetPage() }; const statusType = (s: Status) => ({ 启用: 'success', 禁用: 'info', 已过期: 'warning' } as const)[s]; const openForm = (b?: Batch) => { editing.value = b?.id || ''; Object.assign(form, b ? { name: b.name, validity: b.validity, status: b.status } : { name: '', validity: [], status: '启用' }); visible.value = true }; const save = () => { if (!form.name.trim()) return ElMessage.error('请输入批次名称'); if (editing.value) { const b = batches.find(x => x.id === editing.value); if (b) Object.assign(b, form) } else batches.unshift({ ...form, id: `BT${Date.now()}`, total: 0, pending: 0, unscanned: 0, scanned: 0, winning: 0, createdAt: '2026-08-28 17:30:00' }); visible.value = false; ElMessage.success('批次已保存') }; const remove = async (b: Batch) => { try { await ElMessageBox.confirm(`确定删除批次“${b.name}”吗？删除后无法恢复`, '删除批次', { type: 'warning' }); batches.splice(batches.indexOf(b), 1); ElMessage.success('批次已删除') } catch {} }; const exportData = () => { const rows = [['批次名称', '奖码总数', '待激活数', '未扫码量', '已扫码数', '中奖数量', '创建时间', '批次状态'], ...filtered.value.map(b => [b.name, b.total, b.pending, b.unscanned, b.scanned, b.winning, b.createdAt, b.status])]; const url = URL.createObjectURL(new Blob([`\ufeff${rows.map(r => r.join(',')).join('\n')}`], { type: 'text/csv;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = '总批次.csv'; a.click(); URL.revokeObjectURL(url) }
</script>
<style scoped lang="scss">.heading{display:flex;align-items:center;justify-content:space-between}.batch-table :deep(.first-column .cell){padding-left:16px}.batch-table :deep(.last-column .cell){padding-right:16px}</style>
